const maxWords = Math.ceil(targetWords * 1.08);
const revisionInstruction = revision ? '\n\nDURATION REVISION REQUIRED: the first narration was ' + (revision.actualDurationSeconds || '?') + 's instead of ' + requestedDuration + 's. Write a narration that fits the EXACT duration.' : '';

const textProvider = brief.textProvider || $env.AI_TEXT_PROVIDER || 'cloudflare';
const textModel = brief.textModel || (textProvider === 'gemini' ? ($env.GEMINI_TEXT_MODEL || 'gemini-2.5-flash') : ($env.CLOUDFLARE_TEXT_MODEL || '@cf/meta/llama-3.1-8b-instruct'));
const imageProvider = brief.imageProvider || $env.AI_IMAGE_PROVIDER || 'cloudflare';
const imageModel = brief.imageModel || $env.CLOUDFLARE_IMAGE_MODEL || '@cf/black-forest-labs/flux-1-schnell';

const prompt = 'Create a ' + requestedDuration + '-second vertical short-form video.\n\nTopic: ' + brief.topic + '\nLanguage: ' + (brief.language || 'English') + '\nContent style: ' + (brief.contentStyle || 'Cinematic') + '\nVisual style: ' + (brief.visualStyle || 'Cinematic') + '\nVoice tone: ' + (brief.voiceTone || 'Warm narrator') + '\nScene count: ' + (brief.sceneCount || 5) + '\n\nWrite a narration of approximately ' + targetWords + ' words. The narration must contain between ' + minWords + ' and ' + maxWords + ' words. Write a complete, detailed voiceover that fills the full video duration. Do not return early.\n\nIMPORTANT: Before returning the response, count the narration words internally. If the count is outside the required range, expand or shorten the narration until it is within range.\n\nReturn ONLY valid JSON (no markdown fences, no extra text) with this structure:\n{\n  "title": "string",\n  "description": "string (60-80 words)",\n  "hashtags": ["tag1", "tag2", "tag3", "tag4", "tag5"],\n  "fullScenes": 7,\n  "scenes": [\n    {\n      "sceneIndex": 0,\n      "narration": "narration for this scene",\n      "caption": "on-screen text",\n      "imagePrompt": "detailed visual description for image generation",\n      "durationSeconds": 4,\n      "motion": "zoom_in|zoom_out|pan_left|pan_right|static",\n      "transition": "cut|fade|crossDissolve|wipe_left|wipe_right"\n    }\n  ]\n}\n\nThe sum of all scene durationSeconds must equal ' + requestedDuration + ' seconds.\n\nKeep the JSON compact and proportionate to the ' + requestedDuration + '-second video: brief one-to-two-sentence image prompts, short captions, and only the scenes needed to fill the duration. Do not pad with extra scenes or verbose prose.' + revisionInstruction;

return [{ json: {
  jobId: job.id,
  prompt,
  requestedDuration,
  voiceWordsPerMinute,
  targetWords,
  minWords,
  maxWords,
  provider: textProvider,
  textModel: textModel,
  imageProvider: imageProvider,
  imageModel: imageModel,
  durationValidation: revision,
  durationAttempt: Number(request.durationAttempt || 0),
  wordCountRevisionAttempt: Number(request.wordCountRevisionAttempt || 0)
} }];

const response = $input.first().json;
const raw = response.result ?? '';
let text = typeof raw === 'string' ? raw : JSON.stringify(raw);
// Remove code fences and any text after the closing fence
text = text.replace(/^\s*\x60\x60\x60(?:json)?\s*/i, '');
