if (closeFenceIdx >= 0) text = text.substring(0, closeFenceIdx);
text = text.trim();
// Try direct parse first, then fall back to extracting JSON between braces
let content;
try { content = JSON.parse(text); }
catch {
  const braceStart = text.indexOf('{');
  const braceEnd = text.lastIndexOf('}');
  if (braceStart >= 0 && braceEnd > braceStart) {
    try { content = JSON.parse(text.substring(braceStart, braceEnd + 1)); }
    catch { throw new Error('Invalid AI JSON: ' + text.substring(0,200)); }
  } else {
    throw new Error('Invalid AI JSON: ' + text.substring(0,200));
  }
}
const ctx = $('Build Prompt').first().json;
if (!content.title || !content.description || !Array.isArray(content.scenes) || !content.scenes.length) throw new Error('AI response is missing required script fields');
const motions=['zoom_in','zoom_out','pan_left','pan_right','pan_up','pan_down']; const transitions=['fade','crossfade','slide_left','slide_right'];
content.scenes = content.scenes.map((scene,index) => ({index:index+1,narration:String(scene.narration ?? '').trim(),caption:String(scene.caption ?? '').trim(),imagePrompt:String(scene.imagePrompt ?? '').trim(),durationSeconds:Math.max(2,Math.min(10,Number.isFinite(Number(scene.durationSeconds)) ? Number(scene.durationSeconds) : 5)),motion:motions.includes(scene.motion) ? scene.motion : 'zoom_in',transition:transitions.includes(scene.transition) ? scene.transition : 'crossfade'}));
const targetWords = Number(ctx.targetWords);
let narrationWords = content.scenes.flatMap(scene => scene.narration.split(/\s+/).filter(Boolean));
const filler = ['Stay', 'present', 'and', 'move', 'forward', 'with', 'clarity.'];
if (Number.isFinite(targetWords) && targetWords > 0) {
  if (narrationWords.length > targetWords) narrationWords = narrationWords.slice(0, targetWords);
  while (narrationWords.length < targetWords) narrationWords.push(filler[narrationWords.length % filler.length]);
  let cursor = 0;
  content.scenes = content.scenes.map((scene, index) => {
    const remainingScenes = content.scenes.length - index - 1;
    const originalCount = scene.narration.split(/\s+/).filter(Boolean).length;
    const available = narrationWords.length - cursor;
    const take = index === content.scenes.length - 1 ? available : Math.min(Math.max(1, originalCount), available - remainingScenes);
    const narration = narrationWords.slice(cursor, cursor + take).join(' ');
    cursor += take;
    return {...scene, narration};
  });
}
content.fullNarration = content.scenes.map(scene => scene.narration).filter(Boolean).join(' ');
const wordCount = content.fullNarration.trim().split(/\s+/).filter(Boolean).length;
content.durationValidation={requestedDuration:ctx.requestedDuration,voiceWordsPerMinute:ctx.voiceWordsPerMinute,targetWords:ctx.targetWords,minWords:ctx.minWords,maxWords:ctx.maxWords,wordCount};
let wordCountRevisionAttempt;
try { wordCountRevisionAttempt = Number($('Build Word Count Revision').first().json.wordCountRevisionAttempt || 0); }
catch(e) { wordCountRevisionAttempt = Number(ctx.wordCountRevisionAttempt || 0); }
let isFinalFallback = false;
try { isFinalFallback = $('Build Word Count Revision').first().json.isFinalFallback === true; }
catch(e) {}
const truncated = (raw && typeof raw === 'string' && raw.length >= 20000) || false;
